/*Table structure for table `stokfifodetail` */

DROP TABLE IF EXISTS `stokfifodetail`;

CREATE TABLE `stokfifodetail` (
  `idstokfifodetail` int NOT NULL AUTO_INCREMENT,
  `idstokfifo` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `tglkeluar` datetime DEFAULT NULL,
  `idtransaksi` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `jenistransaksi` enum('Penjualan','Retur Pembelian','Konversi Stok','Stok Opname') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `jumlahkeluar` int DEFAULT NULL,
  `hargasatuan` decimal(18,2) DEFAULT NULL,
  `subtotal` decimal(18,2) DEFAULT NULL,
  `inserted_date` datetime DEFAULT NULL,
  PRIMARY KEY (`idstokfifodetail`),
  KEY `idtransaksi` (`idtransaksi`),
  KEY `jenistransaksi` (`jenistransaksi`),
  KEY `idstokfifo` (`idstokfifo`),
  CONSTRAINT `stokfifodetail_ibfk_1` FOREIGN KEY (`idstokfifo`) REFERENCES `stokfifo` (`idstokfifo`)
